cd /Users/se/shared/antarium/Antarium; python3 - <<'EOF'
p='Sources/Antarium/Core/TranscriptStats.swift'
s=open(p).read()
old='''        // A record that names no model and used nothing — Claude Code's
        // `<synthetic>` messages — adds nothing to any bill. Filed under the
        // unpriceable empty key it made the whole session's cost unavailable.
        // Usage that is real but unattributed is still filed there, because
        // guessing its model would be inventing a price.
        if model == nil, input == 0, output == 0, cacheWrite5m == 0,
           cacheWrite1h == 0, cacheRead == 0 { return true }
'''
assert old in s; s=s.replace(old,'')
old='''        for (key, usage) in usageByModel {
            guard let rate = rateFor(key.isEmpty ? nil : key),'''
new='''        for (key, usage) in usageByModel {
            // Nothing used costs nothing at any rate, including an unknown
            // one. Claude Code's `<synthetic>` messages name no model and
            // carry zero usage; requiring a price for them made the whole
            // session's cost unavailable. Unattributed usage that is real
            // still has no price, because guessing its model would be
            // inventing one.
            if usage.input == 0, usage.output == 0, usage.cacheWrite5m == 0,
               usage.cacheWrite1h == 0, usage.cacheRead == 0 { continue }
            guard let rate = rateFor(key.isEmpty ? nil : key),'''
assert old in s; s=s.replace(old,new)
open(p,'w').write(s)
EOF
./test.sh --filter 'EstimatedCostTests|TranscriptBoundary|ArchitectureContract|MoneyAndCost' 2>&1 | grep -E '✘|Test run with' | head -6

